namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public string Category { get; set; } = "Breakfast";
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "Flour, Eggs, Milk, Butter, Sugar, Baking powder", Steps = "1. Mix dry ingredients\n2. Whisk wet ingredients\n3. Combine and cook on griddle", AverageRating = 4.5, RatingCount = 12 },
        new() { Id = 2, Title = "Avocado Toast", Category = "Breakfast", Ingredients = "Bread, Avocado, Lemon juice, Salt, Red pepper flakes", Steps = "1. Toast bread\n2. Mash avocado with lemon and salt\n3. Spread on toast and season", AverageRating = 4.2, RatingCount = 8 },
        new() { Id = 3, Title = "Caesar Salad", Category = "Lunch", Ingredients = "Romaine lettuce, Parmesan, Croutons, Caesar dressing, Lemon", Steps = "1. Chop lettuce\n2. Toss with dressing\n3. Top with croutons and parmesan", AverageRating = 4.0, RatingCount = 6 },
        new() { Id = 4, Title = "Grilled Chicken Wrap", Category = "Lunch", Ingredients = "Chicken breast, Tortilla, Lettuce, Tomato, Ranch dressing", Steps = "1. Grill chicken\n2. Slice and arrange in tortilla\n3. Add veggies and dressing, wrap tightly", AverageRating = 4.3, RatingCount = 10 },
        new() { Id = 5, Title = "Spaghetti Carbonara", Category = "Dinner", Ingredients = "Spaghetti, Pancetta, Eggs, Parmesan, Black pepper", Steps = "1. Cook pasta\n2. Fry pancetta\n3. Mix eggs with cheese\n4. Toss hot pasta with pancetta, then egg mixture", AverageRating = 4.8, RatingCount = 20 },
        new() { Id = 6, Title = "Beef Stir Fry", Category = "Dinner", Ingredients = "Beef strips, Soy sauce, Broccoli, Bell pepper, Garlic, Ginger, Rice", Steps = "1. Marinate beef in soy sauce\n2. Stir fry vegetables\n3. Cook beef and combine\n4. Serve over rice", AverageRating = 4.4, RatingCount = 15 },
        new() { Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "Butter, Sugar, Brown sugar, Eggs, Vanilla, Flour, Chocolate chips", Steps = "1. Cream butter and sugars\n2. Add eggs and vanilla\n3. Mix in flour and chips\n4. Bake at 375°F for 10 min", AverageRating = 4.9, RatingCount = 25 },
        new() { Id = 8, Title = "Tiramisu", Category = "Desserts", Ingredients = "Mascarpone, Espresso, Ladyfingers, Cocoa powder, Sugar, Eggs", Steps = "1. Mix mascarpone with egg yolks and sugar\n2. Dip ladyfingers in espresso\n3. Layer with cream\n4. Dust with cocoa", AverageRating = 4.7, RatingCount = 18 },
    ];

    private int _nextId = 9;

    public List<string> GetCategories() => _recipes.Select(r => r.Category).Distinct().ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(RecipeSubmission submission)
    {
        _recipes.Add(new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps
        });
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}

